macro_rules! completions {
    () => {
        # [doc = " Main entry point for completion. We run completion as a two-phase process."] # [doc = ""] # [doc = " First, we look at the position and collect a so-called `CompletionContext`."] # [doc = " This is a somewhat messy process, because, during completion, syntax tree is"] # [doc = " incomplete and can look really weird."] # [doc = ""] # [doc = " Once the context is collected, we run a series of completion routines which"] # [doc = " look at the context and produce completion items. One subtlety about this"] # [doc = " phase is that completion engine should not filter by the substring which is"] # [doc = " already present, it should give all possible variants for the identifier at"] # [doc = " the caret. In other words, for"] # [doc = ""] # [doc = " ```ignore"] # [doc = " fn f() {"] # [doc = "     let foo = 92;"] # [doc = "     let _ = bar$0"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " `foo` *should* be present among the completion variants. Filtering by"] # [doc = " identifier prefix/fuzzy match should be done higher in the stack, together"] # [doc = " with ordering of completions (currently this is done by the client)."] # [doc = ""] # [doc = " # Speculative Completion Problem"] # [doc = ""] # [doc = " There's a curious unsolved problem in the current implementation. Often, you"] # [doc = " want to compute completions on a *slightly different* text document."] # [doc = ""] # [doc = " In the simplest case, when the code looks like `let x = `, you want to"] # [doc = " insert a fake identifier to get a better syntax tree: `let x = complete_me`."] # [doc = ""] # [doc = " We do this in `CompletionContext`, and it works OK-enough for *syntax*"] # [doc = " analysis. However, we might want to, eg, ask for the type of `complete_me`"] # [doc = " variable, and that's where our current infrastructure breaks down. salsa"] # [doc = " doesn't allow such \"phantom\" inputs."] # [doc = ""] # [doc = " Another case where this would be instrumental is macro expansion. We want to"] # [doc = " insert a fake ident and re-expand code. There's `expand_speculative` as a"] # [doc = " workaround for this."] # [doc = ""] # [doc = " A different use-case is completion of injection (examples and links in doc"] # [doc = " comments). When computing completion for a path in a doc-comment, you want"] # [doc = " to inject a fake path expression into the item being documented and complete"] # [doc = " that."] # [doc = ""] # [doc = " IntelliJ has CodeFragment/Context infrastructure for that. You can create a"] # [doc = " temporary PSI node, and say that the context (\"parent\") of this node is some"] # [doc = " existing node. Asking for, eg, type of this `CodeFragment` node works"] # [doc = " correctly, as the underlying infrastructure makes use of contexts to do"] # [doc = " analysis."] pub fn completions (db : & RootDatabase , config : & CompletionConfig < '_ > , position : FilePosition , trigger_character : Option < char > ,) -> Option < Vec < CompletionItem > > { let (ctx , analysis) = & CompletionContext :: new (db , position , config , trigger_character) ? ; let mut completions = Completions :: default () ; if trigger_character == Some ('(') { if let CompletionAnalysis :: NameRef (NameRefContext { kind : NameRefKind :: Path (path_ctx @ PathCompletionCtx { kind : PathKind :: Vis { has_in_token } , .. } ,) , .. }) = analysis { completions :: vis :: complete_vis_path (& mut completions , ctx , path_ctx , has_in_token) ; } return Some (completions . into ()) ; } if trigger_character == Some ('_') && ctx . original_token . kind () == syntax :: SyntaxKind :: UNDERSCORE && let CompletionAnalysis :: NameRef (NameRefContext { kind : NameRefKind :: Path (path_ctx @ PathCompletionCtx { kind : PathKind :: Type { .. } | PathKind :: Pat { .. } , .. } ,) , .. }) = analysis && path_ctx . is_trivial_path () { return None ; } { let acc = & mut completions ; match analysis { CompletionAnalysis :: Name (name_ctx) => completions :: complete_name (acc , ctx , name_ctx) , CompletionAnalysis :: NameRef (name_ref_ctx) => { completions :: complete_name_ref (acc , ctx , name_ref_ctx) } CompletionAnalysis :: Lifetime (lifetime_ctx) => { completions :: lifetime :: complete_label (acc , ctx , lifetime_ctx) ; completions :: lifetime :: complete_lifetime (acc , ctx , lifetime_ctx) ; } CompletionAnalysis :: String { original , expanded : Some (expanded) } => { completions :: extern_abi :: complete_extern_abi (acc , ctx , expanded) ; completions :: format_string :: format_string (acc , ctx , original , expanded) ; completions :: env_vars :: complete_cargo_env_vars (acc , ctx , original , expanded) ; completions :: ra_fixture :: complete_ra_fixture (acc , ctx , original , expanded) ; } CompletionAnalysis :: UnexpandedAttrTT { colon_prefix , fake_attribute_under_caret : Some (attr) , extern_crate , } => { completions :: attribute :: complete_known_attribute_input (acc , ctx , colon_prefix , attr , extern_crate . as_ref () ,) ; } CompletionAnalysis :: UnexpandedAttrTT { .. } | CompletionAnalysis :: String { .. } => () , } } Some (completions . into ()) }
    };
}

completions!()